PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS user.schema_migrations(version INTEGER PRIMARY KEY,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user.characters(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL DEFAULT 'Персонаж',class_id TEXT NOT NULL,server TEXT NOT NULL DEFAULT '',faction TEXT NOT NULL DEFAULT '',current_level INTEGER NOT NULL DEFAULT 45,current_gs INTEGER NOT NULL DEFAULT 0,primary_mode TEXT NOT NULL DEFAULT 'pve',play_context TEXT NOT NULL DEFAULT 'solo',active_build_id TEXT,pvp_enabled INTEGER NOT NULL DEFAULT 0,is_active INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user.character_items(character_id INTEGER NOT NULL REFERENCES characters(id) ON DELETE CASCADE,item_id INTEGER NOT NULL,slot TEXT,obtained INTEGER NOT NULL DEFAULT 0,equipped INTEGER NOT NULL DEFAULT 0,enhancement INTEGER NOT NULL DEFAULT 0,favorite INTEGER NOT NULL DEFAULT 0,manastones_json TEXT NOT NULL DEFAULT '[]',soul_binding_json TEXT NOT NULL DEFAULT '{}',theostone_id TEXT,PRIMARY KEY(character_id,item_id));
CREATE TABLE IF NOT EXISTS user.character_skills(character_id INTEGER NOT NULL REFERENCES characters(id) ON DELETE CASCADE,skill_id INTEGER NOT NULL,current_level INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(character_id,skill_id));
CREATE TABLE IF NOT EXISTS user.character_systems(character_id INTEGER NOT NULL REFERENCES characters(id) ON DELETE CASCADE,system_slug TEXT NOT NULL,value_json TEXT NOT NULL DEFAULT '{}',completed INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(character_id,system_slug));
CREATE TABLE IF NOT EXISTS user.character_checklist(character_id INTEGER NOT NULL REFERENCES characters(id) ON DELETE CASCADE,activity_id INTEGER NOT NULL,completion_count INTEGER NOT NULL DEFAULT 0,reset_at TEXT,PRIMARY KEY(character_id,activity_id));
CREATE TABLE IF NOT EXISTS user.favorite_builds(character_id INTEGER NOT NULL REFERENCES characters(id) ON DELETE CASCADE,build_id TEXT NOT NULL,PRIMARY KEY(character_id,build_id));
CREATE TABLE IF NOT EXISTS user.app_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user.update_history(id INTEGER PRIMARY KEY AUTOINCREMENT,provider_id TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,previous_version TEXT,new_version TEXT,added_count INTEGER NOT NULL DEFAULT 0,changed_count INTEGER NOT NULL DEFAULT 0,removed_count INTEGER NOT NULL DEFAULT 0,message TEXT);
